:root {
  --red: #ff0000;
  --red-deep: #b00013;
  --red-soft: #e63946;
  --black: #111;
  --charcoal: #141414;
  --panel: #1b1b1b;
  --panel-2: #242424;
  --white: #fff;
  --muted: #bdbdbd;
  --line: rgba(255,255,255,.14);
  --shadow: 0 24px 80px rgba(0,0,0,.45);
  --font-head: 'Oswald', 'Arial Narrow', Impact, sans-serif;
  --font-body: 'Inter', 'Helvetica Neue', Arial, sans-serif;
}

* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body {
  margin: 0;
  background: var(--black);
  color: var(--white);
  font-family: var(--font-body);
  line-height: 1.6;
  overflow-x: hidden;
}
body::before {
  content: '';
  position: fixed;
  inset: 0;
  z-index: -3;
  background:
    radial-gradient(circle at 20% 0%, rgba(255,0,0,.2), transparent 28rem),
    radial-gradient(circle at 85% 25%, rgba(176,0,19,.18), transparent 26rem),
    linear-gradient(180deg, #080808 0%, var(--charcoal) 48%, #0a0a0a 100%);
}
body::after {
  content: '';
  position: fixed;
  inset: 0;
  z-index: -2;
  pointer-events: none;
  opacity: .18;
  background-image: linear-gradient(rgba(255,255,255,.04) 1px, transparent 1px), linear-gradient(90deg, rgba(255,255,255,.04) 1px, transparent 1px);
  background-size: 48px 48px;
  mask-image: linear-gradient(to bottom, #000, transparent 85%);
}

a { color: inherit; text-decoration: none; }
img { max-width: 100%; display: block; }
button, input, select { font: inherit; }
button { cursor: pointer; }

.top-bar {
  background: linear-gradient(90deg, var(--red-deep), var(--red), var(--red-deep));
  color: var(--white);
  text-align: center;
  font-size: .82rem;
  font-weight: 900;
  letter-spacing: .12em;
  text-transform: uppercase;
  padding: .58rem 1rem;
}
.top-bar a { text-decoration: underline; text-underline-offset: 3px; }

.site-header {
  position: sticky;
  top: 0;
  z-index: 50;
  backdrop-filter: blur(18px);
  background: rgba(10,10,10,.86);
  border-bottom: 1px solid var(--line);
}
.nav {
  max-width: 1220px;
  margin: 0 auto;
  padding: 1rem 1.25rem;
  display: flex;
  align-items: center;
  gap: 1rem;
}
.logo {
  display: inline-flex;
