h2 { font-size: clamp(2.8rem, 7vw, 6.1rem); letter-spacing: -.035em; }
h3 { font-size: clamp(1.55rem, 3vw, 2.3rem); letter-spacing: -.02em; }
p { color: var(--muted); margin: 0; }
.lede { font-size: clamp(1.05rem, 2vw, 1.35rem); max-width: 760px; }

.hero {
  min-height: 78vh;
