.schedule-table tr:hover td { background: rgba(255,0,0,.08); }

.toggle-shell { display: grid; grid-template-columns: 320px 1fr; gap: 1.5rem; }
.toggle-tabs { display: grid; gap: .8rem; align-self: start; }
