.faq-list { display: grid; gap: .85rem; }
.faq-item { border: 1px solid var(--line); background: rgba(255,255,255,.04); }
.faq-question {
  width: 100%;
  border: 0;
  background: transparent;
  color: var(--white);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: 1.35rem;
  text-align: left;
  font-family: var(--font-head);
  font-size: clamp(1.4rem, 3vw, 2rem);
  text-transform: uppercase;
}
.faq-question span:last-child { color: var(--red); font-family: var(--font-body); }
.faq-answer { max-height: 0; overflow: hidden; transition: max-height .3s ease; }
.faq-answer p { padding: 0 1.35rem 1.35rem; max-width: 880px; }
.faq-item.open .faq-answer { max-height: 220px; }

.feature-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1rem; }
