.workout-types { display: grid; grid-template-columns: repeat(5, 1fr); gap: .8rem; }
.type-pill { border: 1px solid var(--line); padding: 1.2rem; min-height: 120px; display: grid; align-content: end; background: linear-gradient(145deg, rgba(255,0,0,.13), rgba(255,255,255,.03)); }
