@media (max-width: 1060px) {
  .nav { flex-wrap: wrap; }
  .menu-toggle { display: inline-flex; margin-left: auto; background: transparent; border: 1px solid var(--line); color: var(--white); padding: .65rem .8rem; text-transform: uppercase; letter-spacing: .1em; }
